import os
from typing import Any, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def extract_layout(
    document: Union[str, bytes],
    *,
    api_endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
    features: Optional[List[str]] = None,
    output_content_format: str = "text",
) -> Dict[str, Any]:
    endpoint = api_endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = api_key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    if isinstance(document, str):
        with open(document, "rb") as f:
            body = f.read()
    elif isinstance(document, (bytes, bytearray)):
        body = bytes(document)
    else:
        raise TypeError("document must be a file path or bytes")

    poller = client.begin_analyze_document(
        model_id="prebuilt-layout",
        body=body,
        features=features,
        output_content_format=output_content_format,
    )
    result = poller.result()

    pages_out: List[Dict[str, Any]] = []
    for page in getattr(result, "pages", []) or []:
        lines_out: List[Dict[str, Any]] = []
        for line in getattr(page, "lines", []) or []:
            lines_out.append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": getattr(line, "polygon", None),
                    "spans": [
                        {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                        for s in (getattr(line, "spans", None) or [])
                    ],
                }
            )

        words_out: List[Dict[str, Any]] = []
        for word in getattr(page, "words", []) or []:
            words_out.append(
                {
                    "content": getattr(word, "content", None),
                    "confidence": getattr(word, "confidence", None),
                    "polygon": getattr(word, "polygon", None),
                    "span": (
                        {
                            "offset": getattr(getattr(word, "span", None), "offset", None),
                            "length": getattr(getattr(word, "span", None), "length", None),
                        }
                        if getattr(word, "span", None) is not None
                        else None
                    ),
                }
            )

        selection_marks_out: List[Dict[str, Any]] = []
        for mark in getattr(page, "selection_marks", []) or []:
            selection_marks_out.append(
                {
                    "state": getattr(mark, "state", None),
                    "confidence": getattr(mark, "confidence", None),
                    "polygon": getattr(mark, "polygon", None),
                    "span": (
                        {
                            "offset": getattr(getattr(mark, "span", None), "offset", None),
                            "length": getattr(getattr(mark, "span", None), "length", None),
                        }
                        if getattr(mark, "span", None) is not None
                        else None
                    ),
                }
            )

        pages_out.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
                "lines": lines_out,
                "words": words_out,
                "selection_marks": selection_marks_out,
            }
        )

    tables_out: List[Dict[str, Any]] = []
    for table in getattr(result, "tables", []) or []:
        cells_out: List[Dict[str, Any]] = []
        for cell in getattr(table, "cells", []) or []:
            cells_out.append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "content": getattr(cell, "content", None),
                    "kind": getattr(cell, "kind", None),
                    "bounding_regions": [
                        {
                            "page_number": getattr(br, "page_number", None),
                            "polygon": getattr(br, "polygon", None),
                        }
                        for br in (getattr(cell, "bounding_regions", None) or [])
                    ],
                    "spans": [
                        {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                        for s in (getattr(cell, "spans", None) or [])
                    ],
                }
            )

        tables_out.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": getattr(br, "polygon", None),
                    }
                    for br in (getattr(table, "bounding_regions", None) or [])
                ],
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(table, "spans", None) or [])
                ],
                "cells": cells_out,
            }
        )

    paragraphs_out: List[Dict[str, Any]] = []
    for paragraph in getattr(result, "paragraphs", []) or []:
        paragraphs_out.append(
            {
                "content": getattr(paragraph, "content", None),
                "role": getattr(paragraph, "role", None),
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": getattr(br, "polygon", None),
                    }
                    for br in (getattr(paragraph, "bounding_regions", None) or [])
                ],
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(paragraph, "spans", None) or [])
                ],
            }
        )

    sections_out: List[Dict[str, Any]] = []
    for section in getattr(result, "sections", []) or []:
        sections_out.append(
            {
                "elements": list(getattr(section, "elements", []) or []),
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(section, "spans", None) or [])
                ],
            }
        )

    figures_out: List[Dict[str, Any]] = []
    for figure in getattr(result, "figures", []) or []:
        figures_out.append(
            {
                "caption": getattr(getattr(figure, "caption", None), "content", None)
                if getattr(figure, "caption", None) is not None
                else None,
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": getattr(br, "polygon", None),
                    }
                    for br in (getattr(figure, "bounding_regions", None) or [])
                ],
                "spans": [
                    {"offset": getattr(s, "offset", None), "length": getattr(s, "length", None)}
                    for s in (getattr(figure, "spans", None) or [])
                ],
            }
        )

    return {
        "provider": "azure-document-intelligence",
        "model_id": "prebuilt-layout",
        "api_version": getattr(result, "api_version", None),
        "content": getattr(result, "content", None),
        "pages": pages_out,
        "tables": tables_out,
        "paragraphs": paragraphs_out,
        "sections": sections_out,
        "figures": figures_out,
    }
